from pathlib import Path
import json, html, collections
O=Path('outputs'); (O/'data').mkdir(exist_ok=True)
def esc(s): return html.escape(str(s))
def table(head,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def p(s): return '<p>'+s+'</p>'
def ul(items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def box(s): return '<aside class="note">'+s+'</aside>'
def a(url,label): return '<a href="'+url+'">'+label+'</a>'
sections=[]
def section(i,title,body): sections.append((i,title,body))

section('scope','01 / Decision brief',p('<strong>Build the story around one damaged shipment becoming a reviewable case.</strong> FreightClaimKit should feel like a precise, considered enterprise company: physical cargo, transparent evidence, explicit responsibility and human judgment. Its first commercial experiment remains an evidence-completeness audit. All five offers remain distinct and visible.')+p('The recommended narrative is <strong>incident → evidence → discrepancy → authority → reviewer action → evaluation</strong>. A continuous cargo-and-dossier object gives the site coherence; different chapter compositions give it variety. Luxury comes from typography, material quality, measured pacing and exact information, rather than constant spectacle.')+table(['Decision','Specification'],[
['Company','<strong>FreightClaimKit</strong>. Concept 42; logistics and knowledge sector. Freight Trestle is the superseded working name from the supplied brief.'],
['Buyer / user','U.S. shipper or 3PL claims manager with recurring damage/shortage cases and an accountable budget; claims analyst operates the workbench. Contracting/insurance counsel validates standing and permitted handling.'],
['Positioning','A provenance-first evidence audit before anyone files a freight claim. Proposed value: make evidence gaps, contradictory values and review ownership visible.'],
['Vision','Every freight claim enters review with its evidence gaps and authority visible, rather than discovering avoidable omissions after submission.'],
['Mission','Shorten preparation and improve documentation integrity without making legal, insurance or settlement decisions. This is intent, not a measured outcome.'],
['Commercial ambition','The user’s $100,000 ambition sets the craft and business aspiration. It is not a validated valuation, website budget, subscription price or customer commitment.'],
['Current deliverable','Research, IA, page plans, visual directions, motion specifications and synthetic design fixtures. No production product, live claim submission, real document collection, deployment or working authentication is delivered here.'],
['Claim status','Research-stage concept. No real customers, integrations, revenue, recovery improvement, operating SaaS or accepted pricing has been demonstrated.'],
['First wedge','Freight Desk: a standalone, permissioned retrospective 20-case evidence audit for one carrier/mode, with named rule and workflow owners.']
])+box('<strong>Instruction handling.</strong> The current request controls: use FreightClaimKit and give the uploaded master guide priority over conflicting brief wording. The guide’s own default “brief first” sentence does not undo that explicit instruction. Therefore the one-page validation narrative becomes the homepage within a complete multi-page IA; it does not remove product, platform, company, pricing or access pages. The brief supplies product facts, constraints and experiments. Embedded builder instructions describe later execution, not authorization to deploy, spend, contact buyers or operate a claims service.')+p('All substantive brief requirements are mapped in the coverage register. Duplicate passages are consolidated. Historical naming/domain notes and internal build decisions are preserved in the handoff rather than presented as current company claims. Public research/methodology content can explain the validation plan without exposing an internal instruction dump.'))

section('research','02 / Research and reference findings',p('Research completed 27 October 2026 through the configured Perplexity high research preset. Live browser inspection covered Linear’s homepage, Ramp Bill Pay and Dragonfly. Seven reference captures are included. The supplied 16 PNGs were reviewed as visual references; no video was attached. No claim is made to have inspected the user’s missing video or every page of each reference site.')+table(['Reference / evidence','What was established','Application to FreightClaimKit'],[
[a('https://www.ups.com/us/en/supplychain/tools/cargo-claims','UPS cargo-claims guidance')+' · primary source','Cargo guidance identifies supporting shipping/delivery documents, invoices, packing lists and other evidence as applicable. Incomplete supporting material can delay or jeopardize a claim.','Use a document checklist as a sourced workflow reference, not as a universal carrier rule or guaranteed sufficient packet.'],
[a('https://www.ups.com/us/en/supplychain/about/freight-terms-of-service','UPS freight terms index')+' · primary source','Terms are differentiated by service; applicability requires the actual contract and transport context.','Separate notice, formal claim and other time requirements. No universal countdown; unresolved applicability stays “Verify.”'],
[a('https://freightclaims.com/our-software/','FreightClaims software')+' · vendor-described capabilities','AI email intake/OCR, document organization, communications, task workflows and deadlines already overlap the concept. Vendor claims are not independent effectiveness evidence.','Comparison must test incremental gaps and preparation work against the buyer’s current setup. Never use “first,” “only,” or a fabricated feature victory table.'],
[a('https://linear.app/','Linear homepage')+' · live inspected','Large left-aligned headline above a detailed product scene; persistent navigation; subsequent intake chapter pairs text with a conversation-to-work-item visual. Product states changed during inspection, but timing was not instrumented.','Use recognizable case actions and a consistent UI vocabulary. Keep product scenes large enough to read. Do not import dark styling everywhere or copy customer logos.'],
[a('https://ramp.com/accounts-payable','Ramp Bill Pay')+' · live inspected','White two-column hero, an animated invoice/approval scene, then a workflow chapter with successive text states and a shared visual area. Reverse scrolling returned to that chapter. Precise scrub versus autoplay behavior was not isolated.','Use source → extracted field → discrepancy → reviewer task. Use distinct layouts after the walkthrough. Keep the form off the hero until the visitor understands the evidence workflow.'],
[a('https://dragonfly.com/','Dragonfly')+' · live inspected','The .xyz address redirects to .com. Black/orange opening, persistent compact navigation, large serif chapter typography and an evolving patterned background. Scroll moved through About, a large typographic interlude, and Writing.','Adopt the sense of chapters and changing scale. Avoid blurred body copy, abstract noise and a long intro that delays product comprehension.'],
[a('https://www.awwwards.com/case-study-dragonfly-by-studio-freight.html','Studio Freight’s Dragonfly case study')+' · studio-authored technique source','Describes a scroll-based clip-path fold, scrubbed background fades and sticky horizontal sections for that version. The currently inspected sequence did not verify those horizontal mechanics.','Use a fold from container wall into document pane, plus one bounded horizontal evidence journey. Treat this as documented historical technique, not proof of today’s exact code.'],
[a('https://bakkenbaeck.com/case/ramp','Bakken & Bæck: Ramp')+' · studio reference','Documents an adaptable graphic system and UI-related animation.','Design a consistent material and document family, while letting each section explain a different operation.'],
[a('https://www.samsara.com/products','Samsara product portfolio')+' / '+a('https://10clouds.com/case-studies/samsara/','10Clouds case study')+' · researched','Industrial product portfolio and a studio account of operational animation/3D illustration. Not live motion-tested in this study.','Connect physical goods to software evidence. Use distinct product pages and portfolio clarity; do not borrow fleet telemetry as a claim capability.'],
[a('https://lusion.co/','Lusion')+' / '+a('https://lusion.co/projects/atlas_motion/','Atlas Motion')+' · researched','Studio-led 3D and manufacturing storytelling references. Not live motion-tested here.','Selective cinematic materiality for the hero; HTML/SVG for core document reading. This is craft inspiration, not a template.'],
[a('https://stripe.com/payments','Stripe Payments')+' · researched','Concrete workflow examples accompany the product proposition.','Let every major claim have a matching visual and detail route. Avoid importing global coverage or operating proof.']
])+p('<strong>Reference reading:</strong> Linear informs UI clarity; Ramp informs document choreography; Dragonfly informs chapter rhythm; the user’s cargo/evidence images supply the subject and materials. No single reference supplies the whole design.')+'<div class="capture-grid">'+''.join('<figure><img loading="lazy" src="reference-captures/'+f+'" alt="'+esc(t)+'"><figcaption>'+t+'</figcaption></figure>' for f,t in [('linear-intake.png','Linear · product-specific intake chapter'),('ramp-hero.png','Ramp · product hero and workflow scene'),('ramp-workflow.png','Ramp · active workflow copy and shared visual'),('dragonfly-hero.png','Dragonfly · cinematic opening'),('dragonfly-about.png','Dragonfly · persistent scene and editorial chapter'),('dragonfly-scroll-type.png','Dragonfly · typographic scale transition')])+'</div>')

section('directions','03 / Three visual territories',p('The three generated images are separate art-direction studies, displayed in the order below. They establish composition and visual character; they are not implementation screenshots, approved copy or tested interfaces.')+table(['Territory','Identity and visual system','Scroll signature / strongest use'],[
['01 · Evidence Atelier','Warm ivory, forest-charcoal, aged copper; editorial serif headline, clean UI sans. Pearl corrugated cargo, glass document planes, diffuse light and careful negative space.','The container opens; evidence layers separate; the camera settles into a readable dossier. Strongest overall fit for the light, premium and trustworthy brief.'],
['02 · Inspection Theatre','Graphite opening, warm metallic accents, ivory explanatory chapters; bold controlled sans typography. One architectural inspection frame around a cargo unit.','A sweep identifies a discrepancy, then resolves into a source highlight and assigned review task. Strong cinematic launch; the frame is an evidence metaphor, not a physical scanning product.'],
['03 · Claim Atlas','Warm white, pale sage, dark forest and a small amber exception accent; technical editorial layout with orthogonal lines and readable labels.','One case stays central while cargo owner, 3PL, insurer and counsel roles enter. Route/context layers become a responsibility diagram. Strongest for multi-party explanation.']
])+p('<strong>Selected direction:</strong> the user selected Claim Atlas (option 3) and rejected the cream background as dull. Use the crisp-white v2 revision: white, silver-gray, emerald and graphite. The earlier Evidence Atelier recommendation is superseded. Preserve the central dossier, party diagram and product index.')+''.join('<figure class="direction"><img loading="lazy" src="visual-directions/'+f+'" alt="FreightClaimKit generated visual direction '+str(i)+'; concept art only"><figcaption>Visual direction '+str(i)+' · generated concept study</figcaption></figure>' for i,f in [(1,'01-evidence-atelier.png'),(2,'02-inspection-theatre.png'),(3,'03-claim-atlas.png')])+box('<strong>Image QA corrections before any build:</strong> Direction 1 places a date near “Deadline: verify”; remove it—FC-208 has no verified deadline. Direction 1 also invents extra quantities/document labels; use the fixture instead. Direction 2’s “faster resolution” line is unproven and its module descriptions drift; replace them with the exact product inventory below. Direction 3 labels the comparison as shipper versus carrier invoice; it must be a draft damage schedule versus the commercial invoice. Across all options, insurer responsibility is conditional on the applicable policy, and role identity never establishes standing. Generated logo forms are exploratory; none is approved or cleared.')+p('The PNG references are moodboard material only. Recreate original assets; do not reuse their embedded images, phone chrome, personal notifications, stock marks or proprietary forms. The attached image set supports modular cargo, transparent layers, architectural frames and role-specific geometry. It does not support dramatic wreckage, robotics, an airport scanner or unexplained metallic node clouds.'))

section('brand','04 / Brand foundation and graphical language',p('Proposed brand character: <strong>exact, composed, accountable, tangible, discerning</strong>. The repeating visual motif is an open case frame: it can hold a cargo cube, document page or unresolved gap. Its open corner means review is still in progress, not certified or approved.')+table(['Role','Proposed specification'],[
['Logo / favicon','Explore a compact open-container/case-bracket mark paired with FreightClaimKit. Avoid a checkmark or official-looking seal as the brand symbol. After direction selection: vector primary, reverse, monochrome and compact lockups; SVG/ICO/32/180/192/512px icons; social cover. Set clear space to one mark-stroke module, minimum 20px mark and 140px horizontal wordmark, then optically test. No final logo clearance implied.'],
['Background / surface','#FFFFFF crisp white; #F1F5F6 cool neutral; #DCE5E9 brushed silver; #101C20 graphite evidence chapter. Predominantly bright white with deliberate dark chapter contrast. No cream, beige or warm haze.'],
['Text / accent','#202D2A primary; #53605A secondary; #AC582D copper accent. Copper signals a selected finding or editorial emphasis, not automatic approval. Verify all final color combinations.'],
['Functional status','Success #246347, warning #875213, error #A3392F, information #38566C, focus #6B44B5. Every state also gets a label and icon. The general brand stays distinct from status coding.'],
['Display typography',a('https://fonts.google.com/specimen/Newsreader','Newsreader')+' 400/500 for editorial section headlines. Use Manrope for the main hero headline as in selected option 3. Desktop H1 72–88px / 0.98–1.06; mobile 40–48px / 1.05. H2 44–56px desktop, 30–36px mobile.'],
['UI / body typography',a('https://fonts.google.com/specimen/Manrope','Manrope')+' 400/500/600. Body 17–18px / 1.55; UI 14–16px / 1.45; captions no smaller than 12px. Tabular numerals for money and dates. H3 24–28px, H4 20px, H5 18px, H6 16px; avoid multiple tiny uppercase styles.'],
['Licensing','Both proposed font families use SIL OFL sources. Retain notices when distributing files: '+a('https://github.com/google/fonts/blob/main/ofl/newsreader/OFL.txt','Newsreader license')+' and '+a('https://github.com/google/fonts/blob/main/ofl/manrope/OFL.txt','Manrope license')+'. Self-host approved subsets with font-display: swap.'],
['Layout','1440px design canvas; 1280px content maximum; 72–80px desktop gutter, 24px mobile. 12-column desktop / 4-column mobile. Reading measure 60–68 characters. Section padding 112–160px desktop, 64–80px mobile.'],
['Spacing / surface','4, 8, 12, 16, 24, 32, 48, 64, 96, 128px rhythm. UI corners 8px; media corners 16px; modest 1px borders. Shadows explain document elevation, never surround every block.'],
['Buttons','48–52px height, stable labels, restrained arrow motion and directional surface wipe. Primary, outline, text and icon variants. Visible focus, hover, pressed, disabled, loading, success and error states.'],
['Navigation','72px desktop header, shrinking only to 64px after entry. Product mega menu lists all five offers with a short job description. Mobile drawer includes all destinations, Escape/dismiss, focus return and scroll lock.'],
['Iconography','Consistent 1.5–2px stroke icons on a 24px grid. Evidence file, BOL, signature, photo, discrepancy, source, history, owner, rule, export. Official LinkedIn/Crunchbase marks only for actual profile links; otherwise a labeled inactive state.']
])+table(['Concept','Visual encoding','Meaning / constraint'],[
['Cargo owner','Solid cargo cube','Goods and potential loss; not automatic right to claim.'],
['3PL agent','Two or three connected modular blocks','Coordination and handling within documented delegation.'],
['Insurer','Outlined architectural frame','Coverage/assessment role subject to policy and authority; no implied insurer endorsement.'],
['Contracting/insurance counsel','Separate verification bracket','Standing and permitted handling review. Avoid a seal that looks like certified approval.'],
['Claims analyst','Central dossier surface','Investigation, corrections, evidence chase and dated next action.'],
['Missing evidence','Open slot + dashed outline + “Missing”','Absence is distinct from illegible, contradictory and not applicable.'],
['Uncertain OCR','Amber underline + source crop + “Review”','Model output remains a hypothesis; no invented delivery notation.'],
['Verified source field','Solid link + reviewer identity/history','A reviewed field in the demo, not a legal determination.'],
['Geographic context','Quiet schematic origin → handoff → delivery map','Show context of evidence creation; never animated tracking dots implying live logistics telemetry.'],
['Money','Aligned ledger with units and source references','Separate invoice value, draft claimed amount, submitted amount and verified recovery. Null remains unknown, never zero.']
])+p('Use at least eight distinct visual types: cargo still life, document stack, evidence strip, three-pane workbench, role topology, amount reconciliation ledger, rule/source card, and evaluation chart. The styling connects them; the function makes each chapter unique.'))

products=[
('Freight Desk','freight-desk','POD/photo/BOL evidence completeness auditor','Claims analyst; claims manager budget','POD, BOL, invoices, packing list, photos → source inventory → configurable checklist → unresolved gaps → human-reviewed audit export','A cargo section unfolds into five document slots; the missing signed-POD slot stays open.','Standalone intake audit; first paid pilot wedge. $400 / retrospective 20-case bundle, then $8 / audited intake case are test hypotheses only.'),
('Freight Review','freight-review','Carrier-specific deadline and notice tracker with verified rule owner','Claims manager with contracting/insurance counsel','Carrier, mode, jurisdiction, actual contract/version and trigger dates → applicability review → separately verified notice/deadline tasks','A timeline remains undated until a source/version/owner card is attached; unknown dates visibly stay Verify.','Proposed standalone offer. No price supplied. No universal rule set or countdown.'),
('Freight Proof','freight-proof','Value and damage schedule reconciler against invoices','Claims analyst; claims manager','Invoice lines, quantities, damage schedule, repair/inspection information if relevant → reconcile amounts → record exceptions/corrections','Two aligned ledgers bridge only on matching source line IDs; $240 draft discrepancy remains a review task.','Proposed standalone offer. No price supplied. Reconciled value is not an automatic payout estimate.'),
('Freight Signal','freight-signal','Claimant-approved submission packet generator and status tracker','Authorized claimant / claims manager; analyst prepares','Reviewed evidence and rule checklist → packet manifest → claimant review → approved external workflow/status history','A packet assembles behind a permission gate; export shows unresolved items; public demo has no filing action.','Proposed standalone offer. No price supplied. First MVP demonstrates human-reviewed export only; future submission always requires scoped human approval.'),
('Freight Report','freight-report','Recovery analytics and packaging/root-cause prevention report','Claims manager plus separate loss-prevention/packaging budget owner','Verified submitted/recovered amounts and case classifications → comparable outcomes → packaging/root-cause hypotheses → prevention report','Transparent paired bars with an explicit unknown cohort, then a carton construction diagram tied to case evidence.','Proposed standalone offer. Separate prevention budget. No price supplied and no recovery-rate promise.')]
section('products','05 / Full product inventory',p('Use the current brand prefix with the supplied module-name stems: <strong>FreightClaimKit Freight Desk, FreightClaimKit Freight Review, FreightClaimKit Freight Proof, FreightClaimKit Freight Signal and FreightClaimKit Freight Report</strong>. In navigation, shorten to the stem. These are proposed module names, not verified trademarks or live plans.')+''.join('<article class="product"><div class="eyebrow">PROPOSED MODULE · '+str(i)+'</div><h3>'+n+'</h3>'+table(['Item','Specification'],[['Job',job],['User / budget',user],['Workflow',flow],['Signature visual',visual],['Commercial boundary',price],['Route','<code>/products/'+slug+'</code>']])+'</article>' for i,(n,slug,job,user,flow,visual,price) in enumerate(products,1))+p('Each product page must include: specific hero → buyer problem → inputs → workflow and exceptions → features with UI evidence → outputs → permissions/rules → how it fits the shared platform → evaluation method → scope/pricing → FAQ → product-selected pilot/demo request. The screenshots and workflow differ for every product; this is not one template with renamed headings.'))

